/* iTeal — общий для всех страниц скрипт: картинки (base64), URL вебхука,
   escapeHtml, шапка/иллюстрация, навигация между страницами и хранение
   ФИО/email в localStorage (страницы теперь настоящие отдельные адреса,
   а не вкладки одной страницы, поэтому анкету спрашиваем один раз на
   главной и передаём между страницами через localStorage, а не через
   переменную в памяти). Подключается тегом <script src="shared.js">
   раньше собственного <script> каждой страницы. */

var LOGO_SRC = "data:image/png;base64,";
  var PROGRESS_CAT_SRC = "data:image/png;base64,";
  var HERO_SRC = "data:image/jpeg;base64,";

var WEBHOOK_URL = "";

  /* =========================================================
     3. ГЕНЕРАЦИЯ ПАР: классический round-robin (circle method)
     n тем нумеруются 0..n-1. За n-1 раундов каждая пара тем
     встречается ровно один раз; мы берём первые ROUNDS раундов —
     это гарантирует, что каждая тема получает ROUNDS РАЗНЫХ
     соперников и появляется в тесте ровно ROUNDS раз.
     ========================================================= */

  

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  var PROFILE_KEY = "iteal_talent_test_profile";
  function getProfile() {
    try {
      var raw = localStorage.getItem(PROFILE_KEY);
      var p = raw ? JSON.parse(raw) : null;
      return (p && p.name && p.email) ? p : null;
    } catch (e) { return null; }
  }
  function saveProfile(p) {
    try { localStorage.setItem(PROFILE_KEY, JSON.stringify(p)); } catch (e) {}
  }
  function requireProfile() {
    var p = getProfile();
    if (!p) { window.location.href = "index.html"; return null; }
    return p;
  }

  function headerHtml(navHtml) {
    return '<div class="app-header"><a href="index.html" aria-label="На главную"><img class="logo" src="' + LOGO_SRC + '" alt="iTeal"></a>' + (navHtml || '') + '</div>';
  }

  // Кнопка "наверх страницы" — добавляется сама на любую страницу,
  // подключившую shared.js (включая будущие новые страницы сайта).
  (function initTotop() {
    document.body.insertAdjacentHTML(
      "beforeend",
      '<button type="button" class="it-totop" id="toTop" aria-label="Наверх" title="Наверх">↑</button>'
    );
    document.getElementById("toTop").addEventListener("click", function () {
      var rm = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      window.scrollTo({ top: 0, behavior: rm ? "auto" : "smooth" });
    });
  })();

  function heroImageHtml() {
    return '<img class="hero-img" src="' + HERO_SRC + '" alt="" aria-hidden="true">';
  }

  // \u0412\u0435\u0440\u0445\u043d\u0435\u0435 \u043c\u0435\u043d\u044e \u0442\u0435\u043f\u0435\u0440\u044c \u0434\u0432\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u0430 \u0441 \u0432\u044b\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u043c\u0438 \u0441\u043f\u0438\u0441\u043a\u0430\u043c\u0438 (\u043d\u0435 \u043f\u043b\u043e\u0441\u043a\u0438\u0439 \u0440\u044f\u0434
  // \u0441\u0441\u044b\u043b\u043e\u043a): "\u0414\u043b\u044f \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432" (\u0442\u0435\u0441\u0442 \u043d\u0430 \u0442\u0430\u043b\u0430\u043d\u0442\u044b, \u0442\u0435\u0441\u0442 \u043d\u0430 IQ) \u0438 "\u0414\u043b\u044f \u0422\u0430\u043b\u0430\u043d\u0442\u043e\u0432"
  // (\u043f\u043e\u043a\u0430 \u043f\u0443\u0441\u0442\u043e \u2014 \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u043c \u043f\u043e\u0437\u0436\u0435). active \u2014 id \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u0441\u0441\u044b\u043b\u043a\u0438 ("talents"/
  // "iq"/null), \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u0434\u0441\u0432\u0435\u0442\u0438\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u044b\u0439 \u043f\u0443\u043d\u043a\u0442 \u0438
  // \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 \u0440\u0430\u0437\u0434\u0435\u043b, \u0434\u0435\u0440\u0435\u0432\u043e \u043f\u0443\u043d\u043a\u0442\u043e\u0432 \u043d\u0438\u0436\u0435 \u043e\u0431\u0449\u0435\u0435 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0441\u0442\u0440\u0430\u043d\u0438\u0446.
  var NAV_SECTIONS = [
    { id: "candidates", label: "\u0414\u043b\u044f \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432", items: [
      { href: "talents.html", label: "\u0422\u0435\u0441\u0442 \u043d\u0430 \u0442\u0430\u043b\u0430\u043d\u0442\u044b", key: "talents" },
      { href: "iq.html", label: "\u0422\u0435\u0441\u0442 \u043d\u0430 IQ", key: "iq" }
    ] },
    { id: "talents-team", label: "\u0414\u043b\u044f \u0442\u0430\u043b\u0430\u043d\u0442\u043e\u0432", href: "talent-gate.html" }
  ];
  function navHtml(active, onlyIds, prevNext) {
    var sections = onlyIds ? NAV_SECTIONS.filter(function (s) { return onlyIds.indexOf(s.id) !== -1; }) : NAV_SECTIONS;
    var prevHtml = prevNext && prevNext.prev
      ? '<a href="' + prevNext.prev.href + '" class="nav-trigger">← ' + prevNext.prev.label + '</a>'
      : '';
    var nextHtml = prevNext && prevNext.next
      ? '<a href="' + prevNext.next.href + '" class="nav-trigger">' + prevNext.next.label + ' →</a>'
      : '';
    return '<nav class="topnav">' +
      prevHtml +
      '<a href="index.html" class="nav-trigger nav-home-link">' +
        '<i data-lucide="home" width="14" height="14" stroke-width="2"></i>' +
        'Главная' +
      '</a>' +
      sections.map(function (section) {
        if (section.href) {
          return '<a href="' + section.href + '" class="nav-trigger">' + section.label + '</a>';
        }
        var hasActive = section.items.some(function (it) { return it.key === active; });
        var itemsHtml = section.items.length
          ? section.items.map(function (it) {
              return '<a href="' + it.href + '" class="nav-menu-link' + (it.key === active ? " active" : "") + '">' + it.label + '</a>';
            }).join("")
          : '<p class="nav-menu-empty">\u0421\u043a\u043e\u0440\u043e \u043f\u043e\u044f\u0432\u044f\u0442\u0441\u044f \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b</p>';
        return '<div class="nav-item">' +
          '<button type="button" class="nav-trigger' + (hasActive ? " active" : "") + '" data-menu="' + section.id + '">' +
            section.label + '<i data-lucide="chevron-down" width="14" height="14" stroke-width="2"></i>' +
          '</button>' +
          '<div class="nav-menu" id="menu-' + section.id + '">' + itemsHtml + '</div>' +
        '</div>';
      }).join("") +
      nextHtml +
    '</nav>';
  }
  // \u041e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442/\u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0432\u044b\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u043e \u043a\u043b\u0438\u043a\u0443 \u043d\u0430 \u0435\u0433\u043e \u043a\u043d\u043e\u043f\u043a\u0443, \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442
  // \u0432\u0441\u0435 \u043f\u0440\u0438 \u043a\u043b\u0438\u043a\u0435 \u0441\u043d\u0430\u0440\u0443\u0436\u0438. \u0412\u044b\u0437\u044b\u0432\u0430\u0442\u044c \u043f\u043e\u0441\u043b\u0435 \u043a\u0430\u0436\u0434\u043e\u0439 \u0432\u0441\u0442\u0430\u0432\u043a\u0438 navHtml() \u0432 DOM \u2014
  // innerHTML \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0441\u0442\u0430\u0440\u044b\u0435 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0438.
  function bindNavDropdowns() {
    var items = document.querySelectorAll(".nav-item");
    items.forEach(function (item) {
      var trigger = item.querySelector(".nav-trigger");
      trigger.addEventListener("click", function (e) {
        e.stopPropagation();
        var wasOpen = item.classList.contains("open");
        items.forEach(function (i) { i.classList.remove("open"); });
        if (!wasOpen) item.classList.add("open");
      });
    });
    document.addEventListener("click", function () {
      items.forEach(function (i) { i.classList.remove("open"); });
    });
  }

  // \u041e\u0431\u0449\u0430\u044f \u0430\u043d\u043a\u0435\u0442\u0430 \u0424\u0418\u041e/email \u2014 \u0440\u0430\u043d\u044c\u0448\u0435 \u0436\u0438\u043b\u0430 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u043e\u0439, \u0442\u0435\u043f\u0435\u0440\u044c \u043b\u044e\u0431\u0430\u044f
  // \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0435\u0451 \u043f\u0440\u044f\u043c\u043e \u043d\u0430 \u043c\u0435\u0441\u0442\u0435 (\u0432\u043c\u0435\u0441\u0442\u043e \u0440\u0435\u0434\u0438\u0440\u0435\u043a\u0442\u0430 \u043d\u0430 \u043f\u0443\u0441\u0442\u0443\u044e
  // \u0433\u043b\u0430\u0432\u043d\u0443\u044e) \u0438 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u0435\u0440\u0435\u0440\u0435\u043d\u0434\u0435\u0440\u0438\u0442\u044c \u0441\u0435\u0431\u044f \u043f\u043e\u0441\u043b\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0447\u0435\u0440\u0435\u0437 onDone.
  function gateHtml() {
    var p = getProfile() || { name: "", email: "" };
    return '<span class="kicker">iTeal \u00b7 \u043d\u043e\u0432\u044b\u043c \u0432 \u043a\u043e\u043c\u0430\u043d\u0434\u0435</span>' +
      '<h1>\u041f\u0440\u0438\u0432\u0435\u0442!</h1>' +
      '<p class="lead">\u0420\u0430\u0434\u044b, \u0447\u0442\u043e \u0442\u044b \u043e\u0442\u043a\u043b\u0438\u043a\u043d\u0443\u043b\u0441\u044f(\u0430\u0441\u044c) \u043d\u0430 \u043d\u0430\u0448\u0443 \u0432\u0430\u043a\u0430\u043d\u0441\u0438\u044e. \u041f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043d\u0430\u0447\u0430\u0442\u044c \u2014 \u0443\u043a\u0430\u0436\u0438 \u0424\u0418\u041e (\u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0438\u043c\u044f) \u0438 \u043f\u043e\u0447\u0442\u0443 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u043e\u043d\u0438 \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u044f\u0442\u0441\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0433\u043e \u0441\u0430\u0439\u0442\u0430.</p>' +
      '<div class="card">' +
        '<label for="p-name">\u0424\u0418\u041e</label>' +
        '<input type="text" id="p-name" placeholder="\u0418\u0432\u0430\u043d\u043e\u0432 \u0418\u0432\u0430\u043d \u0418\u0432\u0430\u043d\u043e\u0432\u0438\u0447" value="' + escapeHtml(p.name) + '">' +
        '<label for="p-email">Email</label>' +
        '<input type="email" id="p-email" placeholder="you@iteal.expert" value="' + escapeHtml(p.email) + '">' +
        '<button class="primary" id="profile-next" disabled>\u0414\u0430\u043b\u044c\u0448\u0435</button>' +
      '</div>';
  }
  function bindGate(onDone) {
    var nameInput = document.getElementById("p-name");
    var emailInput = document.getElementById("p-email");
    var nextBtn = document.getElementById("profile-next");
    function validate() {
      var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value.trim());
      nextBtn.disabled = !(nameInput.value.trim().length > 1 && emailOk);
    }
    nameInput.addEventListener("input", validate);
    emailInput.addEventListener("input", validate);
    validate();
    nextBtn.addEventListener("click", function () {
      saveProfile({ name: nameInput.value.trim(), email: emailInput.value.trim() });
      onDone();
    });
  }
